int[] arr = new int[1000];

int x = arr[10];                 // A: element at position 10
int pos = indexOf(arr, 42);      // B: position of value 42

int[] sorted = {1, 3, 4, 7, 9, 11, 15, 20};
int steps = 0, lo = 0, hi = sorted.length - 1;
while (lo <= hi) {
    steps++;
    int mid = (lo + hi) / 2;
    if (sorted[mid] == 15) break;
    if (sorted[mid] < 15) lo = mid + 1; else hi = mid - 1;
}
System.out.println(steps);

